import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import logo from '../assets/logo.png';

export default function Login({ onLogin }) {
  const [userType, setUserType] = useState('embarcador');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showModal, setShowModal] = useState(false);

  // Estados do modal cadastro
  const [email, setEmail] = useState('');
  const [cnpj, setCnpj] = useState('');
  const [empresaNome, setEmpresaNome] = useState('');
  const [empresaEndereco, setEmpresaEndereco] = useState('');
  const [buscando, setBuscando] = useState(false);
  const [buscaErro, setBuscaErro] = useState('');
  const [cadastroConfirmado, setCadastroConfirmado] = useState(false);

  const navigate = useNavigate();

  // Função para simular busca via API
  const buscarDadosEmpresa = async () => {
    setBuscaErro('');
    setBuscando(true);
    setEmpresaNome('');
    setEmpresaEndereco('');
    try {
      await new Promise((res) => setTimeout(res, 1500));
      const cnpjValido = /^\d{14}$/.test(cnpj.replace(/\D/g, ''));
      const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
      if (!cnpjValido) throw new Error('CNPJ inválido (deve ter 14 números)');
      if (!emailValido) throw new Error('Email inválido');
      setEmpresaNome('Empresa Exemplo Ltda');
      setEmpresaEndereco('Rua das Flores, 123 - São Paulo, SP');
    } catch (error) {
      setBuscaErro(error.message || 'Erro ao buscar dados da empresa.');
    } finally {
      setBuscando(false);
    }
  };

  const handleCadastrar = () => {
    setCadastroConfirmado(true);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!username || !password) {
      return alert('Preencha todos os campos');
    }

    const user = {
      username,
      role: userType,
      name: userType === 'embarcador'
        ? 'Embarcador Leo'
        : userType === 'transportador'
        ? 'Transportadora XYZ'
        : 'Loja Parceira',
    };
    onLogin(user);

    if (userType === 'embarcador') {
      navigate('/dashboard');
    } else if (userType === 'transportador') {
      navigate('/transportador');
    } else if (userType === 'loja') {
      navigate('/loja/coletas');
    }
  };

  return (
    <>
      <div className="flex items-center justify-center min-h-screen bg-gradient-to-r from-green-400 to-blue-500">
        <div className="bg-white p-10 rounded-lg shadow-lg max-w-md w-full">
          <div className="mb-6 text-center">
            <img src={logo} alt="Leo Madeiras" className="mx-auto mb-4 w-32" />
            <h1 className="text-2xl font-bold">Login Leo Madeiras</h1>
          </div>
          <form onSubmit={handleSubmit} className="space-y-4">
            <select
              className="w-full border rounded px-3 py-2"
              value={userType}
              onChange={(e) => setUserType(e.target.value)}
            >
              <option value="embarcador">Embarcador</option>
              <option value="transportador">Transportador</option>
              <option value="loja">Loja</option> {/* NOVA OPÇÃO */}
            </select>

            <input
              type="text"
              placeholder="Usuário"
              className="w-full border rounded px-3 py-2"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
            />

            <input
              type="password"
              placeholder="Senha"
              className="w-full border rounded px-3 py-2"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />

            <button
              type="submit"
              className="w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition"
            >
              Entrar
            </button>
          </form>

          <div className="mt-4 text-center">
            <button
              onClick={() => setShowModal(true)}
              className="text-sm text-blue-700 underline hover:text-blue-900"
              type="button"
            >
              Seja um Parceiro Leo Cadastre-se Aqui
            </button>
          </div>
        </div>
      </div>

      {/* Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center z-50 p-4">
          <div className="bg-white rounded-lg shadow-lg max-w-md w-full p-6 relative">
            <button
              onClick={() => {
                setShowModal(false);
                setCadastroConfirmado(false);
                setBuscaErro('');
                setEmpresaNome('');
                setEmpresaEndereco('');
                setEmail('');
                setCnpj('');
              }}
              className="absolute top-2 right-2 text-gray-500 hover:text-gray-800 text-xl font-bold"
              aria-label="Fechar"
              type="button"
            >
              &times;
            </button>

            {!cadastroConfirmado ? (
              <>
                <h2 className="text-xl font-bold mb-4 text-center">Cadastro Parceiro Leo</h2>

                <div className="space-y-4">
                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="email">
                      Email
                    </label>
                    <input
                      id="email"
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      className="w-full border rounded px-3 py-2"
                      placeholder="seu@email.com"
                    />
                  </div>

                  <div>
                    <label className="block mb-1 font-semibold" htmlFor="cnpj">
                      CNPJ
                    </label>
                    <input
                      id="cnpj"
                      type="text"
                      value={cnpj}
                      onChange={(e) => setCnpj(e.target.value)}
                      className="w-full border rounded px-3 py-2"
                      placeholder="00.000.000/0001-00"
                    />
                  </div>

                  <button
                    onClick={buscarDadosEmpresa}
                    disabled={buscando || !email || !cnpj}
                    className={`w-full bg-blue-600 text-white py-2 rounded hover:bg-blue-700 transition ${
                      (buscando || !email || !cnpj) && 'opacity-50 cursor-not-allowed'
                    }`}
                    type="button"
                  >
                    {buscando ? 'Buscando...' : 'Buscar Dados Empresa'}
                  </button>

                  {buscaErro && (
                    <p className="text-red-600 mt-2 text-center font-semibold">{buscaErro}</p>
                  )}

                  {empresaNome && (
                    <div className="mt-4 p-3 border rounded bg-green-50">
                      <p><strong>Nome:</strong> {empresaNome}</p>
                      <p><strong>Endereço:</strong> {empresaEndereco}</p>
                    </div>
                  )}

                  {empresaNome && (
                    <button
                      onClick={handleCadastrar}
                      className="w-full bg-green-500 text-white py-2 rounded hover:bg-green-600 transition mt-4"
                      type="button"
                    >
                      Cadastrar
                    </button>
                  )}
                </div>
              </>
            ) : (
              <div className="text-center p-4">
                <h2 className="text-xl font-bold mb-4">Cadastro Confirmado!</h2>
                <p className="mb-2">Enviado por email. Aguarde a liberação ou entre em contato com a Léo Madeiras.</p>
                <button
                  onClick={() => setShowModal(false)}
                  className="mt-4 bg-green-500 text-white py-2 px-6 rounded hover:bg-green-600 transition"
                  type="button"
                >
                  Fechar
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </>
  );
}
