// src/pages/Faturas.js
import React, { useState } from 'react';

export default function Faturas({ user }) {
  const [expandedFatura, setExpandedFatura] = useState(null);

  // Simulando dados das faturas
  const faturas = [
    {
      id: '123456C',
      dtEmissao: '15/06/2025',
      vrFrete: 3500.75,
      status: 'Pendente',
      ctes: [
        { id: '000001', dtEmissao: '10/06/2025', vrFrete: 1500.25 },
        { id: '000002', dtEmissao: '12/06/2025', vrFrete: 2000.50 },
      ],
    },
    {
      id: '654321C',
      dtEmissao: '10/06/2025',
      vrFrete: 1800.00,
      status: 'Autorizada',
      ctes: [
        { id: '000003', dtEmissao: '08/06/2025', vrFrete: 800.00 },
        { id: '000004', dtEmissao: '09/06/2025', vrFrete: 1000.00 },
      ],
    },
  ];

  const toggleExpand = (faturaId) => {
    setExpandedFatura(expandedFatura === faturaId ? null : faturaId);
  };

  return (
    <main className="flex-1 p-6 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-6 text-center">Faturas</h1>

      <div className="bg-white p-6 rounded shadow mb-6 overflow-auto">
        <table className="w-full text-left border-collapse text-sm">
          <thead>
            <tr className="border-b border-gray-300">
              <th className="p-3">DT Emissão</th>
              <th className="p-3">NR Fatura</th>
              <th className="p-3">VR Frete</th>
              <th className="p-3">Status</th>
            </tr>
          </thead>
          <tbody>
            {faturas.map((fatura) => (
              <React.Fragment key={fatura.id}>
                <tr
                  onClick={() => toggleExpand(fatura.id)}
                  className="cursor-pointer hover:bg-green-50"
                >
                  <td className="p-3">{fatura.dtEmissao}</td>
                  <td className="p-3 font-mono">{fatura.id}</td>
                  <td className="p-3">R$ {fatura.vrFrete.toFixed(2)}</td>
                  <td
                    className={`p-3 font-bold ${
                      fatura.status === 'Pendente' ? 'text-red-600' : 'text-green-600'
                    }`}
                  >
                    {fatura.status}
                  </td>
                </tr>
                {expandedFatura === fatura.id && (
                  <tr className="bg-gray-50">
                    <td colSpan={4} className="p-3">
                      <table className="w-full text-left text-xs">
                        <thead>
                          <tr className="border-b border-gray-300">
                            <th className="p-2">DT Emissão</th>
                            <th className="p-2">NR CTE</th>
                            <th className="p-2">VR Frete</th>
                          </tr>
                        </thead>
                        <tbody>
                          {fatura.ctes.map((cte) => (
                            <tr key={cte.id} className="hover:bg-green-100">
                              <td className="p-2">{cte.dtEmissao}</td>
                              <td className="p-2 font-mono">{cte.id}</td>
                              <td className="p-2">R$ {cte.vrFrete.toFixed(2)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </td>
                  </tr>
                )}
              </React.Fragment>
            ))}
          </tbody>
        </table>
      </div>
    </main>
  );
}
