import React, { useState, useEffect } from 'react';
import { Pie } from 'react-chartjs-2';
import 'chart.js/auto';
import { Chart } from 'chart.js';
import ChartDataLabels from 'chartjs-plugin-datalabels';
import {
  Pie as RePie,
  Cell,
  Tooltip,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  ResponsiveContainer,
} from 'recharts';

Chart.register(ChartDataLabels);

const lojas = [
  { codigo: 1000, nome: 'Leo CD' },
  { codigo: 1001, nome: 'Leo Madeiras Gasometro' },
  { codigo: 1003, nome: 'Leo Madeiras Paes Leme' },
  { codigo: 1006, nome: 'Santos' },
  { codigo: 1007, nome: 'São José dos Campos' },
  { codigo: 1008, nome: 'Sampaio' },
  { codigo: 1011, nome: 'Leo Madeiras Aricanduva' },
  { codigo: 1016, nome: 'Leo Madeiras Lapa' },
  { codigo: 1027, nome: 'S.J. do Rio Preto' }
];

// Gerar dados fictícios
const dadosMargemPorLoja = lojas.map((loja) => {
  const valorPago = parseFloat((Math.random() * 5000 + 1000).toFixed(2));
  const valorCobrado = parseFloat((valorPago * (Math.random() * 0.5 + 0.75)).toFixed(2));
  const diferenca = parseFloat((valorCobrado - valorPago).toFixed(2));
  const percentual = ((diferenca / valorPago) * 100).toFixed(2);
  return {
    codigoLoja: loja.codigo,
    nomeLoja: loja.nome,
    valorPago,
    valorCobrado,
    diferenca,
    percentual,
  };
});

export default function Lojas() {
  const [selectedAno, setSelectedAno] = useState(new Date().getFullYear());
  const [mes, setMes] = useState(new Date().getMonth() + 1);
  const [quinzena, setQuinzena] = useState(1);
  const [lojaSelecionadaMargem, setLojaSelecionadaMargem] = useState(null);

  const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#AA336A'];

  return (
    <div className="p-4 space-y-4">
      {/* Filtros */}
      <div className="flex space-x-4 mb-4">
        <select className="border px-2 py-1 rounded" value={selectedAno} onChange={(e) => setSelectedAno(Number(e.target.value))}>
          {[2023, 2024, 2025].map((ano) => (
            <option key={ano} value={ano}>{ano}</option>
          ))}
        </select>
        <select className="border px-2 py-1 rounded" value={mes} onChange={(e) => setMes(Number(e.target.value))}>
          {[...Array(12).keys()].map((m) => (
            <option key={m + 1} value={m + 1}>{m + 1}</option>
          ))}
        </select>
        <select className="border px-2 py-1 rounded" value={quinzena} onChange={(e) => setQuinzena(Number(e.target.value))}>
          <option value={1}>1ª Quinzena</option>
          <option value={2}>2ª Quinzena</option>
        </select>
      </div>

      {/* Primeira linha apenas tabela */}
      <div className="bg-white p-4 rounded shadow">
        <h2 className="text-xl font-semibold mb-4">Margem por Loja (Quinzena Atual)</h2>
        <div className="overflow-auto max-h-96">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr>
                <th className="p-2">Código Loja</th>
                <th className="p-2">Nome Loja</th>
                <th className="p-2">Frete Transportador</th>
                <th className="p-2">Frete Loja</th>
                <th className="p-2">Diferença</th>
                <th className="p-2">%</th>
              </tr>
            </thead>
            <tbody>
              {dadosMargemPorLoja.map((item, index) => (
                <tr
                  key={item.codigoLoja}
                  className={`cursor-pointer hover:bg-green-100 ${lojaSelecionadaMargem === item.codigoLoja ? 'bg-green-200 font-bold' : ''}`}
                  onClick={() => setLojaSelecionadaMargem(item.codigoLoja)}
                >
                  <td className="p-2">{item.codigoLoja}</td>
                  <td className="p-2">{item.nomeLoja}</td>
                  <td className="p-2">R$ {item.valorPago.toFixed(2)}</td>
                  <td className="p-2">R$ {item.valorCobrado.toFixed(2)}</td>
                  <td className={`p-2 ${item.diferenca >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                    {item.diferenca >= 0 ? '▲' : '▼'} R$ {item.diferenca.toFixed(2)}
                  </td>
                  <td className={`p-2 ${item.percentual >= 0 ? 'text-green-600' : 'text-red-600'}`}>{item.percentual}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Segunda linha com gráfico de barras */}
      <div className="bg-white p-4 rounded shadow h-[400px] flex flex-col">
        <h2 className="font-bold mb-2">Margem por Loja (Gráfico de Barras)</h2>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={dadosMargemPorLoja} margin={{ top: 20, right: 30, left: 20, bottom: 40 }}>
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis dataKey="codigoLoja" label={{ value: 'Código Loja', position: 'insideBottom', offset: -10 }} />
            <YAxis label={{ value: 'Valor Pago', angle: -90, position: 'insideLeft' }} />
            <Tooltip formatter={(value) => `R$ ${value.toFixed(2)}`} />
            <Bar dataKey="valorPago" fill="#0088FE" name="Valor Pago">
              {dadosMargemPorLoja.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
