// src/pages/PosicaoFrotas.js
import React, { useState } from 'react';
import { FiTruck } from 'react-icons/fi';
import { PieChart, Pie, Cell, Tooltip, Legend } from 'recharts';

const COLORS = ['#e74c3c', '#3498db', '#2ecc71']; // vermelho, azul, verde
const TRUCK_COLORS = {
  low:  '#e74c3c', // 0–33%
  mid:  '#f1c40f', // 34–99%
  high: '#2ecc71', // 100%
};

const rotasData = [
  { id: 1, status: 'Não Iniciado', rota: '10001', transportadora: 'NOVA DIRECAO TRANSP EIRELI', viagem: '000101', dtEmissao: '01/06/2025', placa: 'ABC-1234', motorista: 'João Silva',    dtEntrega: '', qtAEntregar: 10, qtEntregue: 0 },
  { id: 2, status: 'Em Andamento', rota: '10002', transportadora: 'LUMA EXPRESS TRANSP CARGA LTDA', viagem: '000102', dtEmissao: '02/06/2025', placa: 'DEF-5678', motorista: 'Maria Souza',   dtEntrega: '', qtAEntregar: 8,  qtEntregue: 3 },
  { id: 3, status: 'Encerrado',    rota: '10003', transportadora: 'W.C.CARVALHO TRANSPORTES', viagem: '000103', dtEmissao: '03/06/2025', placa: 'GHI-9012', motorista: 'Carlos Pereira', dtEntrega: '10/06/2025', qtAEntregar: 5, qtEntregue: 5 },
  { id: 4, status: 'Em Andamento', rota: '10004', transportadora: 'NOVA LESTE TRANSPORTES ME', viagem: '000104', dtEmissao: '04/06/2025', placa: 'JKL-3456', motorista: 'Ana Ramos',     dtEntrega: '', qtAEntregar: 12, qtEntregue: 6 },
  { id: 5, status: 'Não Iniciado', rota: '10005', transportadora: 'MARIA LUIZA DA S L TRANSPORTE', viagem: '000105', dtEmissao: '05/06/2025', placa: 'MNO-7890', motorista: 'Bruno Lima',    dtEntrega: '', qtAEntregar: 7, qtEntregue: 0 },
  { id: 6, status: 'Encerrado',    rota: '10006', transportadora: 'B M NATIVIDADE TRANSPORTES', viagem: '000106', dtEmissao: '06/06/2025', placa: 'PQR-2345', motorista: 'Sofia Costa',    dtEntrega: '12/06/2025', qtAEntregar: 9, qtEntregue: 9 },
  { id: 7, status: 'Em Andamento', rota: '10007', transportadora: 'ANDERSON RODRIGUES DOS SANTOS', viagem: '000107', dtEmissao: '07/06/2025', placa: 'STU-6789', motorista: 'Lucas Alves',    dtEntrega: '', qtAEntregar: 11, qtEntregue: 5 },
  { id: 8, status: 'Não Iniciado', rota: '10008', transportadora: 'D SANTANA', viagem: '000108', dtEmissao: '08/06/2025', placa: 'VWX-0123', motorista: 'Mariana Melo',   dtEntrega: '', qtAEntregar: 6, qtEntregue: 0 },
  { id: 9, status: 'Encerrado',    rota: '10009', transportadora: 'GS TLOG TRANSPO E LOG EIRELLI', viagem: '000109', dtEmissao: '09/06/2025', placa: 'YZA-4567', motorista: 'Pedro Rocha',   dtEntrega: '14/06/2025', qtAEntregar: 4, qtEntregue: 4 },
  { id: 10,status: 'Em Andamento', rota: '10010', transportadora: 'L S ALMEIDA TRANSPORTES-ME', viagem: '000110', dtEmissao: '10/06/2025', placa: 'BCD-8901', motorista: 'Beatriz Dias',   dtEntrega: '', qtAEntregar: 15, qtEntregue:10 },
];

// Dados das notas
const notasData = rotasData.reduce((acc, r) => {
  acc[r.id] = Array.from({ length: r.qtAEntregar }, (_, i) => ({
    nf: '' + (10000000 + r.id*100 + i),
    remetente: ['61069373000103','61069373002157','61069373003390','61069373006144'][i % 4],
    peso: (Math.random() * 100).toFixed(2),
    mercadoria: (Math.random() * 2000 + 100).toFixed(2),
    tpEntrega: [50,51,91,92,900][i % 5],
    loja: [1001,1003,1011,1012,1016,1036][i % 6],
  }));
  return acc;
}, {});

// Dados para o PieChart
const entregueCount   = rotasData.filter(r => r.qtEntregue === r.qtAEntregar).length;
const aEntregarCount  = rotasData.reduce((sum, r) => sum + (r.qtAEntregar - r.qtEntregue), 0);
const ocorrenciaCount = rotasData.filter(r => r.status === 'Não Iniciado').length;
const pieTotals = [
  { name: 'Encerrado', value: entregueCount },
  { name: 'A Entregar', value: aEntregarCount },
  { name: 'Ocorrência', value: ocorrenciaCount },
];

export default function PosicaoFrotas() {
  const [periodo, setPeriodo] = useState({ inicio: '', fim: '' });
  const [selectedRota, setSelectedRota] = useState(null);

  const statusColor = {
    'Não Iniciado': 'text-red-600',
    'Em Andamento': 'text-blue-600',
    'Encerrado': 'text-green-800',
  };

  const getTruckColor = (r) => {
    const pct = r.qtEntregue / r.qtAEntregar;
    if (pct === 1) return TRUCK_COLORS.high;
    if (pct > 0.33) return TRUCK_COLORS.mid;
    return TRUCK_COLORS.low;
  };

  return (
    <div className="p-4 space-y-6">

      {/* Filtro e Legenda Caminhões */}
      <div className="flex items-center justify-between mb-4">
        {/* Filtro de Período */}
        <div className="flex items-center space-x-4">
          <label>Período:</label>
          <input
            type="date"
            className="border rounded px-2 py-1"
            value={periodo.inicio}
            onChange={e => setPeriodo(p => ({ ...p, inicio: e.target.value }))}
          />
          <span>até</span>
          <input
            type="date"
            className="border rounded px-2 py-1"
            value={periodo.fim}
            onChange={e => setPeriodo(p => ({ ...p, fim: e.target.value }))}
          />
        </div>

        {/* Legenda Caminhões */}
        <div className="flex items-center space-x-6">
          <div className="flex items-center space-x-2">
            <FiTruck size={20} color={TRUCK_COLORS.low} />
            <span>0 a 33%</span>
          </div>
          <div className="flex items-center space-x-2">
            <FiTruck size={20} color={TRUCK_COLORS.mid} />
            <span>34 a 99%</span>
          </div>
          <div className="flex items-center space-x-2">
            <FiTruck size={20} color={TRUCK_COLORS.high} />
            <span>100%</span>
          </div>
        </div>
      </div>

      {/* Card Rotas */}
      <div className="bg-white p-4 rounded shadow">
        <h2 className="font-semibold mb-4">Rotas</h2>
        <table className="w-full text-sm text-left border-collapse">
          <thead>
            <tr className="border-b">
              <th className="p-2">Status</th>
              <th className="p-2">Rota</th>
              <th className="p-2">Transportadora</th>
              <th className="p-2">Viagem</th>
              <th className="p-2">Emissão</th>
              <th className="p-2">Placa</th>
              <th className="p-2">Motorista</th>
              <th className="p-2">Entrega</th>
              <th className="p-2">A Entregar</th>
              <th className="p-2">Entregue</th>
              <th className="p-2">%</th>
            </tr>
          </thead>
          <tbody>
            {rotasData.map(r => (
              <tr
                key={r.id}
                className="hover:bg-gray-100 cursor-pointer"
                onClick={() => setSelectedRota(r.id)}
              >
                <td className={`p-2 font-semibold ${statusColor[r.status]}`}>{r.status}</td>
                <td className="p-2">{r.rota}</td>
                <td className="p-2">{r.transportadora}</td>
                <td className="p-2">{r.viagem}</td>
                <td className="p-2">{r.dtEmissao}</td>
                <td className="p-2">{r.placa}</td>
                <td className="p-2">{r.motorista}</td>
                <td className="p-2">{r.dtEntrega || '–'}</td>
                <td className="p-2">{r.qtAEntregar}</td>
                <td className="p-2">{r.qtEntregue}</td>
                <td className="p-2"><FiTruck size={20} color={getTruckColor(r)} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Segunda linha: Notas e Gráfico */}
      <div className="grid grid-cols-2 gap-4">
        {/* Card Notas da Rota */}
        <div className="bg-white p-4 rounded shadow">
          <h2 className="font-semibold mb-4">Notas da Rota {selectedRota ?? '…'}</h2>
          {selectedRota && notasData[selectedRota] ? (
            <table className="w-full text-sm text-left border-collapse">
              <thead>
                <tr className="border-b">
                  <th className="p-2">NF</th>
                  <th className="p-2">Remetente</th>
                  <th className="p-2">Peso</th>
                  <th className="p-2">Mercadoria</th>
                  <th className="p-2">TP Entrega</th>
                  <th className="p-2">Loja</th>
                  <th className="p-2">Status</th>
                </tr>
              </thead>
              <tbody>
                {notasData[selectedRota].map((n, idx) => {
                  const rota = rotasData.find(r => r.id === selectedRota);
                  const isDelivered = idx < rota.qtEntregue;
                  return (
                    <tr key={n.nf} className="hover:bg-gray-100">
                      <td className="p-2">{n.nf}</td>
                      <td className="p-2">{n.remetente}</td>
                      <td className="p-2">{n.peso}</td>
                      <td className="p-2">{n.mercadoria}</td>
                      <td className="p-2">{n.tpEntrega}</td>
                      <td className="p-2">{n.loja}</td>
                      <td className={`p-2 font-semibold ${isDelivered ? 'text-green-600' : 'text-blue-600'}`}>
                        {isDelivered ? 'Entregue' : 'A Entregar'}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <p className="text-gray-500">Selecione uma rota acima para ver as notas.</p>
          )}
        </div>

        {/* Gráfico */}
        <div className="bg-white p-4 rounded shadow flex flex-col items-center">
          <h2 className="font-semibold mb-4">Visão Geral de Entregas</h2>
          <PieChart width={300} height={300}>
            <Pie
              data={pieTotals}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              outerRadius={100}
              label={({ percent }) => `${(percent * 100).toFixed(0)}%`}
            >
              {pieTotals.map((_, idx) => (
                <Cell key={idx} fill={COLORS[idx]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend verticalAlign="bottom" />
          </PieChart>
        </div>
      </div>
    </div>
  );
}
